    print(f"\n{key} ({len(grid)}x{len(grid[0])}):")
    for row in grid:
        print(row)

def flood_fill_from_edges(grid):
    """Find all cells reachable from edges (outside area)."""
    rows = len(grid)
    cols = len(grid[0])

    # Background color (most frequent on edges)
    edge_colors = set()
    for r in range(rows):
        if grid[r][0] != 6: edge_colors.add(grid[r][0])
        if grid[r][cols-1] != 6: edge_colors.add(grid[r][cols-1])
    for c in range(cols):
        if grid[0][c] != 6: edge_colors.add(grid[0][c])
        if grid[rows-1][c] != 6: edge_colors.add(grid[rows-1][c])

    # Most common edge color is background
    bg_color = max(edge_colors, key=lambda x: sum(1 for r in range(rows) for c in range(cols) if grid[r][c] == x))

    visited = [[False]*cols for _ in range(rows)]
    stack = []

    # Add all edge cells
    for r in range(rows):
        if not visited[r][0]:
            stack.append((r, 0))
            visited[r][0] = True
        if not visited[r][cols-1]:
            stack.append((r, cols-1))
            visited[r][cols-1] = True
    for c in range(cols):
        if not visited[0][c]:
            stack.append((0, c))
            visited[0][c] = True
        if not visited[rows-1][c]:
            stack.append((rows-1, c))
            visited[rows-1][c] = True

    while stack:
        r, c = stack.pop()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                if grid[nr][nc] == bg_color:
                    visited[nr][nc] = True
                    stack.append((nr, nc))

    return visited, bg_color

